import React from 'react';
import RoleNav from '../components/navigation/RoleNav.jsx';
import './CustomerCare.css';

const CustomerCare = () => {
  const claims = [
    { id: 1, ref: '135402-251203-592423', customer: 'Lupo Chambaka', type: 'Repair · Excess', amount: 'Pending' },
    { id: 2, ref: '135402-251203-592424', customer: 'Aisha Juma', type: 'Repair · Excess', amount: 'Pending' },
  ];

  const handleUpdateAmount = (claimId) => {
    alert(`Updating amount for claim ${claimId}`);
  };

  return (
    <div>
      <RoleNav activeRole="care" onRoleChange={() => {}} />
      <div className="care-container">
        <div className="care-header">
          <i className="fas fa-hand-holding-heart"></i>
          <h3>All Excess Claims Needing Amount Update</h3>
        </div>
        
        <div className="care-list">
          {claims.map(claim => (
            <div key={claim.id} className="care-item">
              <div className="care-detail">
                <span className="label">Claim #</span>
                <span className="value">{claim.ref}</span>
              </div>
              <div className="care-detail">
                <span className="label">Customer</span>
                <span className="value">{claim.customer}</span>
              </div>
              <div className="care-detail">
                <span className="label">Type</span>
                <span className="value">{claim.type}</span>
              </div>
              <div className="care-detail">
                <span className="label">Amount</span>
                <span className="value pending">{claim.amount}</span>
              </div>
              <button 
                className="btn-primary full-width"
                onClick={() => handleUpdateAmount(claim.id)}
              >
                <i className="fas fa-edit"></i> Update Amount
              </button>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default CustomerCare;
